mapM_ok_map.stmt:
theorem mapM_ok_map {α β γ ε : Type} {f : α → Except ε β} {g : β → γ} {k : α → γ}
    (hgk : ∀ a b, f a = .ok b → g b = k a) :
    ∀ {l : List α} {r : List β}, l.mapM f = .ok r → r.map g = l.map k

mergeBy_comm.stmt:
theorem mergeBy_comm {lt eqk : K → K → Bool} {combine : V → V → V}
    (ho : StrictOrder lt eqk) (hc : ∀ x y, combine x y = combine y x) :
    ∀ a b, mergeBy lt eqk combine a b = mergeBy lt eqk combine b a

insertBy_sorted.stmt:
theorem insertBy_sorted {lt eqk : K → K → Bool} {combine : V → V → V}
    (ho : StrictOrder lt eqk) {k : K} {v : V} :
    ∀ l : List (K × V), SortedBy lt l → SortedBy lt (insertBy lt eqk combine k v l)

insertBy_allV.stmt:
theorem insertBy_allV {lt eqk : K → K → Bool} {combine : V → V → V} {P : V → Prop}
    (hP : ∀ x y, P x → P y → P (combine x y)) {k : K} {v : V} (hv : P v) :
    ∀ l : List (K × V), AllV P l → AllV P (insertBy lt eqk combine k v l)

sortedBy_map.stmt:
theorem sortedBy_map {lt : K → K → Bool} {g : K × V → K × V}
    (hg : ∀ p, (g p).1 = p.1) :
    ∀ l : List (K × V), SortedBy lt l → SortedBy lt (l.map g)

mergeBy_allV.stmt:
theorem mergeBy_allV {lt eqk : K → K → Bool} {combine : V → V → V} {P : V → Prop}
    (hP : ∀ x y, P x → P y → P (combine x y)) :
    ∀ a b : List (K × V), AllV P a → AllV P b → AllV P (mergeBy lt eqk combine a b)

prefixedCore_ne_snoc.stmt:
theorem prefixedCore_ne_snoc {x : List UInt8} {p : List Char}
    (hp : ∀ c ∈ p, c ≠ '_') (hlen : 2 ≤ p.length) :
    prefixedCore (encodeBytes x) ≠ p ++ ['_']

prefixedCore_inj.stmt:
theorem prefixedCore_inj {x y : List UInt8}
    (h : prefixedCore (encodeBytes x) = prefixedCore (encodeBytes y)) :
    encodeBytes x = encodeBytes y

toUTF8_data_toList_inj.full:
theorem toUTF8_data_toList_inj {a b : String}
    (h : a.toUTF8.data.toList = b.toUTF8.data.toList) : a = b :=
  String.toByteArray_inj.mp (ByteArray.ext (Array.ext' h))

TableObs.merge_assoc.stmt:
theorem TableObs.merge_assoc {a b c : TableObs}
    (ha : TableObsOk a) (hb : TableObsOk b) (hc : TableObsOk c) :
    TableObs.merge (TableObs.merge a b) c = TableObs.merge a (TableObs.merge b c)

Tables.merge_assoc.stmt:
theorem Tables.merge_assoc {a b c : Tables}
    (ha : TablesOk a) (hb : TablesOk b) (hc : TablesOk c) :
    Tables.merge (Tables.merge a b) c = Tables.merge a (Tables.merge b c)

Tables.merge_right_comm.stmt:
theorem Tables.merge_right_comm {b x y : Tables}
    (hb : TablesOk b) (hx : TablesOk x) (hy : TablesOk y) :
    Tables.merge (Tables.merge b x) y = Tables.merge (Tables.merge b y) x

Tables.upsert_ok.stmt:
theorem Tables.upsert_ok {ts : Tables} {p : Path} {f : TableObs → TableObs}
    (h : TablesOk ts) (hf : ∀ t, TableObsOk t → TableObsOk (f t)) :
    TablesOk (ts.upsert p f)

frame_trans.full:
theorem frame_trans {q : Path} {a b c : Tables}
    (h1 : Frame q a b) (h2 : Frame q b c) : Frame q a c :=
  fun r hr => (h2 r hr).trans (h1 r hr)

frame_widen.full:
theorem frame_widen {q q' : Path} {a b : Tables}
    (hpre : q <+: q') (h : Frame q' a b) : Frame q a b :=
  fun r hr => h r (fun hq'r => hr (hpre.trans hq'r))

recordMember_fits.stmt:
theorem recordMember_fits {ts : Tables} {p : Path} {k : String} {s : Seen}
    (hok : TablesOk ts) (hfit : CountsFit ts) (hroom : Room ts p [k]) :
    CountsFit (recordMember ts p k s)

upsert_lookup_self.stmt:
theorem upsert_lookup_self {ts : Tables} {p : Path} {f : TableObs → TableObs}
    {t : TableObs} (hlk : ts.lookup p = some t) :
    (ts.upsert p f).lookup p = some (f t)

upsert_fits_keep.stmt:
theorem upsert_fits_keep {ts : Tables} {p : Path} {f : TableObs → TableObs}
    (hmem : ∀ t, (f t).members = t.members) (hvis : ∀ t, t.visits ≤ (f t).visits)
    (hfit : CountsFit ts) : CountsFit (ts.upsert p f)

upsert_visit_room.stmt:
theorem upsert_visit_room {ts : Tables} {p : Path} {f : TableObs → TableObs}
    (hmem : ∀ t, (f t).members = t.members) (hvis : ∀ t, (f t).visits = t.visits + 1)
    (hfit : CountsFit ts) (ks : List String) : Room (ts.upsert p f) p ks

recordMember_room.stmt:
theorem recordMember_room {ts : Tables} {p : Path} {k : String} {s : Seen}
    {ks : List String} (hne : ∀ k' ∈ ks, k' ≠ k) (hroom : Room ts p (k :: ks)) :
    Room (recordMember ts p k s) p ks

room_upsert_ne.stmt:
theorem room_upsert_ne {ts : Tables} {p r : Path} {ks : List String}
    {f : TableObs → TableObs} (hne : p ≠ r) (h : Room ts p ks) :
    Room (ts.upsert r f) p ks

observeDocument_fits.full:
theorem observeDocument_fits {cfg : Config} {d : Doc} {ts : Tables}
    (h : observeDocument cfg d = .ok ts) : CountsFit ts :=
  (walk_counts cfg [] [] false d ts h TablesOk.nil countsFit_nil).2

mem_orderTables_complete.full:
theorem mem_orderTables_complete {t : Table} {s : Schema}
    (hn : (s.map Table.path).Nodup) (h : t ∈ s) : t ∈ orderTables s :=
  mem_orderGo_complete _ _ _ hn (Or.inl h)

layoutOf_member.stmt:
theorem layoutOf_member {nm : Naming} {t : Table} {cols : List Col}
    {c : Column} {col : Col}
    (h : layoutOf nm t = .ok cols) (hc : c ∈ t.columns)
    (hmc : memberCol (generatedNames nm t) c = .ok (some col)) : col ∈ cols

keyTyOf_id_not_ref.stmt:
theorem keyTyOf_id_not_ref {t : Table} {kt : Ty} {c : Column} {q : Path}
    (h : keyTyOf t = .ok kt) (hn : (t.columns.map Column.name).Nodup)
    (hc : c ∈ t.columns) (hid : c.name = "id") (hty : c.field.ty = .ref q) : False

genModule_accessor.stmt:
theorem genModule_accessor {nm : Naming} {t : Table} {m : Module} {cols : List Col} {c : Col}
    (h : genModule nm t = .ok m) (hl : layoutOf nm t = .ok cols) (hc : c ∈ cols) :
    Decl.value c.name (.arrow (.named "t") (colTyExpr nm c)) ∈ m.decls

genRegistry_decls.full:
theorem genRegistry_decls {s : Schema} {nm : Naming} {m : Module}
    (h : genRegistry s nm = .ok m) : m.decls = [] := by
  unfold genRegistry at h; cases h; rfl

layoutOf_mapM.stmt:
theorem layoutOf_mapM {nm : Naming} {t : Table} {cols : List Col}
    (h : layoutOf nm t = .ok cols) :
    ∃ ms, t.columns.mapM (memberCol (generatedNames nm t)) = .ok ms

gen_module_of.stmt:
theorem gen_module_of {nm : Naming} {s : Schema} {f : File} {t : Table}
    (h : gen nm s = .ok f) (ht : t ∈ s) :
    ∃ m, m ∈ f.modules ∧ genModule nm t = .ok m

gen_module_source.stmt:
theorem gen_module_source {nm : Naming} {s : Schema} {f : File} {m : Module}
    (h : gen nm s = .ok f) (hm : m ∈ f.modules) (hd : m.decls ≠ []) :
    ∃ t, t ∈ s ∧ genModule nm t = .ok m

genModule_accessor_only.stmt:
theorem genModule_accessor_only {nm : Naming} {t : Table} {m : Module}
    {n : String} {X : TyExpr}
    (h : genModule nm t = .ok m)
    (hd : Decl.value n ((TyExpr.named "t").arrow X) ∈ m.decls)
    (hX : ∀ Y Z, X ≠ TyExpr.arrow Y Z) :
    ∃ cols c, layoutOf nm t = .ok cols ∧ c ∈ cols ∧ X = colTyExpr nm c

baseCols_ref.stmt:
theorem baseCols_ref {nm : Naming} {t : Table} {kt : Ty} {c : Col} {p : Path}
    (hkt : keyTyOf t = .ok kt) (hc : c ∈ baseCols nm t kt) (hty : c.ty = .ref p) :
    t.parent = some p

foldl_perm.stmt:
theorem foldl_perm {α β : Type} {f : β → α → β}
    (hrc : ∀ b x y, f (f b x) y = f (f b y) x) :
    ∀ {l₁ l₂ : List α}, l₁.Perm l₂ → ∀ b, l₁.foldl f b = l₂.foldl f b

scalarTy_seeScalar.stmt:
theorem scalarTy_seeScalar {p : String} {d : Doc} {ty : Ty} {b : Bool}
    (hs : d.isScalar = true) (h : seeScalar p d = .ok (.value ty b)) :
    scalarTy d = some ty

matchesField_mono.stmt:
theorem matchesField_mono {s : Schema} {f g : Field} {v : Doc}
    (hty : Ty.le f.ty g.ty) (hn : f.nullable = true → g.nullable = true)
    (h : MatchesField s f v) : MatchesField s g v
